harness.setup_page:
async function(spec) {
  await callbackTab.reload();
  await callbackTab.waitForSelector("#preset:not(:disabled)", { timeout: 60000 });
  await callbackTab.click("#play");
  return await callbackTab.evaluate(`(async()=>{
    const sleep=ms=>new Promise(r=>setTimeout(r,ms));
    const api=async(path,data)=>{const response=await window.sadPetFetch(path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await response.json();if(!response.ok)throw Error(value.error||path);return value;};
    const spec=${JSON.stringify(spec)};
    let preset;
    if(spec.mixed){
      await api('/api/timbres/add',{kind:'oscillators'});
      const root=await api('/api/timbres');
      const active=root.active;
      for(const part of root.timbres)if(part.id!==active&&part.kind!=='master')await api('/api/timbres/remove',{id:part.id});
      preset=await api('/api/preset');
      const template=structuredClone(preset.oscillators.slots[0]);
      preset.oscillators.slots=Array.from({length:8},(_,i)=>({...structuredClone(template),id:i+1,kind:['radias','wavefolder','pcm','wavetable'][i%4],level:.1,transpose:i}));
      preset.oscillators.next_id=9;
      preset.params.filter=1;preset.params.filter2=1;preset.color_chain=[];preset.pre_color_chain=[];
      if(spec.groups){
        preset.rack.modules.splice(1,0,{module:'grains',enabled:true});
        preset.grain_capture={mode:'osc',slots:85};
        preset.grain_groups={advanced:true,groups:Array.from({length:4},()=>({}))};
        preset.interactions={version:1,routes:[
          {source:{kind:'osc',id:4},target:{kind:'osc',id:1},ring:.5,sync:'hard'},
          {source:{kind:'osc',id:1},target:{kind:'group',index:0},sync:spec.births?'hard':'soft',scope:spec.births?'both':'playback'},
          {source:{kind:'group',index:0},target:{kind:'osc',id:8},ring:.5,sync:'soft'},
          {source:{kind:'group',index:1},target:{kind:'group',index:2},ring:.5,sync:'hard',scope:'clock'}
        ]};
      }
      await api('/api/preset',preset);
      await api('/api/transport',{playing:true,midi_gate:true});
      for(const note of [60,64,67,72])await api('/api/note',{kind:'note_on',channel:0,note,velocity:100});
    }
    preset=await api('/api/preset');
    const base=(await api('/api/timbres')).active;
    window.__callbackProfile={api,sleep,preset,base,spec};
    await sleep(5000);
    const state=await window.sadPetState();
    return {preset:state.preset.name,active:base,notes:state.notes,peak:state.peak,grains:state.active_grains,playing:state.playing,modules:state.preset.rack?.modules,oscillators:state.preset.oscillators?.slots?.filter(Boolean).map(s=>({id:s.id,kind:s.kind})),visibility:document.visibilityState};
  })()`);
}

harness.measurement_program:
spec => `(async()=>{
  const {api,sleep,preset,base}=window.__callbackProfile;
  const spec=${JSON.stringify(spec)},seconds=spec.seconds||60;
  const start=await api('/api/diagnostics/memory');
  const visibility=[{at_ms:0,state:document.visibilityState}],actions=[];
  const at=performance.now(),until=at+seconds*1000;
  const changed=()=>visibility.push({at_ms:performance.now()-at,state:document.visibilityState});
  document.addEventListener('visibilitychange',changed);
  const action=async(name,index,fn)=>{
    const label='sad-profile:'+spec.name+':'+name+':'+index;
    performance.mark(label+':start');const begin=performance.now();
    try{return await fn();}
    finally{actions.push({name,index,wall_ms:performance.now()-begin});performance.mark(label+':end');}
  };
  performance.mark('sad-profile:'+spec.name+':start');
  let operations=0;
  if(spec.mode==='scalar'){
    for(let i=0;performance.now()<until;i++){
      await sleep(Math.max(0,at+i*20-performance.now()));
      if(performance.now()>=until)break;
      const begin=performance.now();
      await api('/api/parameters',{position:.35+.25*Math.sin(i/35),filter:.5+.2*Math.sin(i/41)});
      actions.push({name:'parameters',index:i,wall_ms:performance.now()-begin});operations++;
    }
  }else if(spec.mode==='preset'){
    for(let i=0;at+500+i*1000<until;i++){
      await sleep(Math.max(0,at+500+i*1000-performance.now()));
      preset.params.position=.15+(i%8)*.08;
      await action('preset',i,()=>api('/api/preset',preset));operations++;
    }
  }else if(spec.mode==='prepare'){
    for(let i=0;at+500+i*2000<until;i++){
      await sleep(Math.max(0,at+500+i*2000-performance.now()));
      const added=await action('add-drums',i,()=>api('/api/timbres/add',{kind:'drums'}));
      await action('remove-drums',i,()=>api('/api/timbres/remove',{id:added.active}));
      await api('/api/timbres/select',{id:base});operations++;
    }
  }
  await sleep(Math.max(0,until-performance.now()));
  performance.mark('sad-profile:'+spec.name+':end');
  document.removeEventListener('visibilitychange',changed);
  const measured_wall_seconds=(performance.now()-at)/1000;
  const end=await api('/api/diagnostics/memory');
  const state=await window.sadPetState();
  const delta=start.playback_stats&&end.playback_stats?Object.fromEntries(Object.keys(end.playback_stats).filter(k=>typeof end.playback_stats[k]==='number'&&typeof start.playback_stats[k]==='number').map(k=>[k,end.playback_stats[k]-start.playback_stats[k]])):null;
  return {spec,start,end,playback_delta:delta,measured_wall_seconds,audio_seconds:end.current_time-start.current_time,operations,actions,visibility,final:{playing:state.playing,peak:state.peak,notes:state.notes,active_grains:state.active_grains,dropped_grain_births:state.dropped_grain_births,preset:state.preset.name},user_agent:navigator.userAgent};
})()`

harness.driver:
async function(spec){
  const configuration=await setupProfilePage(spec);
  await callbackTab.traceStart({categories:callbackCategories,screenshots:false});
  let measurement,trace;
  try{
    await callbackTab.evaluate(`window.__callbackResult=null;window.__callbackError=null;${profileProgram(spec)}.then(value=>window.__callbackResult=value,error=>window.__callbackError=error.stack);true`);
    await callbackTab.run(async({page})=>{await page.waitForFunction(()=>window.__callbackResult!==null||window.__callbackError!==null,{timeout:1000,polling:1000}).catch(()=>{});});
    await new Promise(resolve=>setTimeout(resolve,(spec.seconds||60)*1000+1000));
    measurement=await callbackTab.evaluate('(()=>{if(window.__callbackError)throw Error(window.__callbackError);if(!window.__callbackResult)throw Error("Measurement has not finished");return window.__callbackResult;})()');
  }finally{
    trace=await callbackTab.traceStop();
    await callbackTab.evaluate('window.sadPetFetch("/api/quit",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"}).then(r=>r.json())');
  }
  const run={name:spec.name,configuration,measurement,trace};callbackRuns.push(run);
  console.log({name:run.name,trace,operations:measurement.operations,wall_s:measurement.measured_wall_seconds,audio_s:measurement.audio_seconds,playback_delta:measurement.playback_delta,peak:measurement.final.peak});
  return run;
}
